public class Animal
{
    public string Name;

    public Animal(string name)
    {
        Name = name;
    }

    // virtual: las clases derivadas PUEDEN sobrescribir este método
    public virtual void MakeSound()
    {
        Debug.Log(Name + " makes a generic sound.");
    }

    public virtual void Attack()
    {
        Debug.Log(Name + " attacks for 10 damage.");
    }
}

public class Dog : Animal
{
    public Dog(string name) : base(name) { }

    // override: reemplaza la implementación de Animal.MakeSound
    public override void MakeSound()
    {
        Debug.Log(Name + " says: Woof!");
    }

    // Dog no sobrescribe Attack(), usa la versión de Animal
}

public class Cat : Animal
{
    public Cat(string name) : base(name) { }

    public override void MakeSound()
    {
        Debug.Log(Name + " says: Meow!");
    }

    public override void Attack()
    {
        // base.Attack() llama a la implementación del padre ANTES de agregar lógica propia
        base.Attack();
        Debug.Log(Name + " scratches for 5 extra damage!");
    }
}

// Polimorfismo: un array de Animal puede contener Dog y Cat
Animal[] animals = new Animal[3];
animals[0] = new Animal("Generic");
animals[1] = new Dog("Rex");
animals[2] = new Cat("Whiskers");

// C# decide en TIEMPO DE EJECUCIÓN qué versión de MakeSound() llamar
foreach (Animal a in animals)
{
    a.MakeSound();
    // Output:
    // Generic makes a generic sound.
    // Rex says: Woof!
    // Whiskers says: Meow!
}

// Esto funciona porque MakeSound() es virtual/override
// Si no fuera virtual, todos llamarían Animal.MakeSound()

