public class Character
{
    public virtual void TakeDamage(int dmg)
    {
        Debug.Log("Character takes " + dmg + " damage.");
    }
}

public class Knight : Character
{
    public override void TakeDamage(int dmg)
    {
        int reduced = dmg / 2;
        Debug.Log("Knight blocks! Takes only " + reduced);
    }
}

public class Enemy
{
    public string Name;
    public virtual void Attack()
    {
        Debug.Log(Name + " attacks for 10 damage.");
    }
}

public class Vampire : Enemy
{
    public override void Attack()
    {
        base.Attack();
        Debug.Log(Name + " drains 5 HP!");
    }
}

public class Animal
{
    public virtual void MakeSound()
    {
        Debug.Log("...");
    }
}

public class Dog : Animal
{
    public new void MakeSound()
    {
        Debug.Log("Woof!");
    }
}

// En otro lugar:
Animal a = new Dog();
a.MakeSound();

Animal[] enemies = new Animal[3];
enemies[0] = new Dog("Rex");
enemies[1] = new Cat("Luna");
enemies[2] = new Animal("Basic");

foreach (Animal a in enemies)
{
    a.MakeSound();
}

